// NIOGEN | n8n/mari/n02_entrada.js — nó "2 · Entrada" do workflow mari_principal (04/11/2026; resolvida → 2v em 05/11, prompt 18;
//   origem pela mensagem pronta (IG)/(FB)/anúncio em 06/11, 0033)
// Normaliza a entrada (rota de teste ou webhook do Chatwoot), aplica o interruptor de modo
// (staticData._modoMari = 'teste' | 'chatwoot'), comandos admin da rota de teste, detecção de mídia
// e rate limit. Sem texto de negócio e sem segredo.

const sd = $getWorkflowStaticData('global');
if (!sd._modoMari) sd._modoMari = 'teste';
const modo = sd._modoMari;

// Conta/caixa próprias da Nio no Chatwoot ("Nio Atendimento", WhatsApp Cloud do 31 2888-1265).
// Nada da conta da Vero — a validação abaixo descarta qualquer evento de outra conta/caixa.
const CONFIG = {
  CHATWOOT_NIO_ACCOUNT: '195428',
  CHATWOOT_NIO_INBOX: '153431',
  MAX_CHAMADAS_HORA: 300,
};

const ex = (n) => { try { return $(n).isExecuted; } catch (e) { return false; } };
const fim = (saida) => [{ json: { encerrar: true, saida } }];

const MIDIA_SO = new Set(['audio', 'voice', 'video', 'sticker', 'document', 'file', 'attachment']);

// Origem pela mensagem pronta (06/11, migration 0033): link da bio do Instagram termina em "(IG)", botão da página do
// Facebook em "(FB)", anúncio da campanha 1 começa com "Vi o anúncio" (INFRA §7). Sem marca = null → o banco grava 'direto'.
// O banco só usa a origem na conversa nova ou numa conversa ainda 'direto' — nunca troca uma origem já conhecida.
const origemDoTexto = (t) => {
  const s = String(t || '');
  if (/\(IG\)|vim pelo instagram/i.test(s)) return 'instagram';
  if (/\(FB\)|vim pela p[áa]gina do facebook/i.test(s)) return 'facebook';
  if (/vi o an[úu]ncio/i.test(s)) return 'meta_ads';
  return null;
};

// v7 (prompts 26 + 27, 06/11): resposta de botão. O Chatwoot entrega o TÍTULO do botão como texto (o id da Meta não
// chega). Plano B aprovado pelo Ricardo (06/11 18h42): títulos com o nome do plano. "Quero o Super" vira a fala
// "Quero o plano Nio Super"; "Detalhes Super" / "Mais detalhes" o 5b · Motor responde com o texto fixo, sem o Claude.
// Se um dia vier o id (plano:<codigo>:quero|detalhes), ele é usado.
const PLANOS_BOTAO = { fibra: 'Fibra', essencial: 'Essencial', super: 'Super', ultra: 'Ultra' };
function textoDoBotao(texto, botaoId) {
  const id = String(botaoId || '');
  const mid = id.match(/^plano:V-REG-([A-Z]+):(quero|detalhes)$/);
  if (mid) {
    const fam = { FIBRA: 'Fibra', ESS: 'Essencial', SUP: 'Super', ULT: 'Ultra' }[mid[1]];
    if (fam) return mid[2] === 'quero' ? `Quero o plano Nio ${fam}` : `Detalhes ${fam}`;
  }
  const t = String(texto || '').trim();
  const q = t.match(/^quero o (fibra|essencial|super|ultra)!?$/i);
  if (q) return `Quero o plano Nio ${PLANOS_BOTAO[q[1].toLowerCase()]}`;
  return t;
}
// Status do Chatwoot (0048, prompt 27 B2): lido em TODO evento já validado e gravado pelo 2t (mari_chatwoot_sync),
// antes dos guards e sem mudar o fluxo da Mari.
function statusDe(conv, convId) {
  if (!conv || !convId) return null;
  return {
    p_chatwoot_conversation_id: String(convId),
    p_status: conv.status || null,
    p_agente: (conv.meta && conv.meta.assignee && conv.meta.assignee.name) || null,
    p_time: (conv.meta && conv.meta.team && conv.meta.team.name) || null,
    p_etiquetas: Array.isArray(conv.labels) ? conv.labels : [],
  };
}

let entrada;

if (ex('1 · Webhook Mari teste')) {
  const body = $('1 · Webhook Mari teste').first().json.body || {};

  // Comandos admin (só pela rota de teste, que já exige o header secreto).
  if (body.admin) {
    const cmd = String(body.admin).toLowerCase().trim();
    if (cmd === 'modo teste' || cmd === 'modo chatwoot') {
      sd._modoMari = cmd.split(' ')[1];
      return fim({ admin: true, modo: sd._modoMari });
    }
    if (cmd === 'status') return fim({ admin: true, modo: sd._modoMari, chamadas_ultima_hora: (sd._apiCalls || []).length, tel_real: sd._telReal ? `…${sd._telReal.slice(-4)}` : null });
    // v7: teste no celular do Ricardo pela rota de ensaio — só ESTE número recebe carrossel/botões de verdade (Graph API).
    const tr = cmd.match(/^tel real (\d{12,13}|off)$/);
    if (tr) { sd._telReal = tr[1] === 'off' ? null : tr[1]; return fim({ admin: true, tel_real: sd._telReal ? `…${sd._telReal.slice(-4)}` : null }); }
    return fim({ admin: true, erro: 'comando desconhecido (use: modo teste | modo chatwoot | status | tel real <55DDDNUMERO> | tel real off)' });
  }

  // A rota de teste funciona nos dois modos (bateria): canal 'teste', resposta só no corpo HTTP,
  // nunca passa pelo Chatwoot (o 2m e o 11 seguem o gatilho, não o interruptor).

  const tel = String(body.telefone || '').replace(/\D/g, '');
  if (!/^\d{10,15}$/.test(tel)) return fim({ erro: 'telefone inválido (só dígitos, com DDI)' });

  let texto = textoDoBotao(body.texto, body.botao_id);
  const midia = String(body.midia || '').toLowerCase().trim();
  if (midia) {
    if (midia === 'image' || midia === 'imagem') texto = ['[Imagem enviada pelo cliente]', texto].filter(Boolean).join('\n');
    else if (midia === 'location' || midia === 'localizacao') texto = ['[Localização enviada pelo cliente]', texto].filter(Boolean).join('\n');
    else if (!texto) texto = `[MIDIA:${MIDIA_SO.has(midia) ? midia : 'attachment'}]`;
  }
  if (!texto) return fim({ erro: 'texto vazio' });

  entrada = {
    canal: 'teste', telefone: tel, nome: String(body.nome || '').trim(), texto,
    // origem 'auto' = a bateria testa a leitura da mensagem pronta (sem marca → 'direto').
    origem: body.origem === 'auto' ? (origemDoTexto(texto) || 'direto') : (body.origem || 'teste'), chatwootConversationId: null,
    // Envio real (Graph API) só para o número liberado pelo admin "tel real" — nunca para outro.
    enviarReal: body.enviar_real === true && !!sd._telReal && tel === sd._telReal,
  };
  // 12/11 (0145): a bateria prova a cadeia de mídia (2a–2b8) mandando midia + midia_url (https) — como um anexo do Chatwoot.
  const urlT = String(body.midia_url || '');
  const tipoT = midia === 'image' || midia === 'imagem' ? 'imagem' : midia === 'audio' || midia === 'voice' ? 'audio' : null;
  if (tipoT && /^https:\/\//.test(urlT)) {
    entrada.anexos = [{ n: 0, tipo: tipoT, mime: null, ext: String(body.midia_ext || '').toLowerCase() || null, tamanho: null, url: urlT,
      cw_transcricao: null, baixar: true }];
    entrada.baixarMidia = true;
    entrada.msgId = `teste${Date.now()}`;
  }
} else if (ex('1c · Webhook Chatwoot')) {
  if (modo !== 'chatwoot') return [];
  const wb = $('1c · Webhook Chatwoot').first().json;

  // Validação de origem (padrão no0 da Renata). O n8n 1.94 não entrega o corpo bruto ao Code, então o
  // HMAC não é recalculado: exige o header de assinatura do Chatwoot bem formado e, depois, conta e caixa
  // exatamente as da Nio. Sem assinatura = erro (vai para mari_erros); outra conta/caixa = descarte calado.
  const sig = String((wb.headers || {})['x-chatwoot-signature'] || '');
  if (!sig) throw new Error('[1c] Header x-chatwoot-signature ausente — requisição bloqueada.');
  if (!/^sha256=[0-9a-f]{64}$/.test(sig)) throw new Error('[1c] Formato de assinatura inválido — requisição bloqueada.');

  const b = wb.body || {};
  const contaId = String(b.account?.id ?? b.account_id ?? '');
  const caixaId = String(b.inbox?.id ?? b.inbox_id ?? b.conversation?.inbox_id ?? '');
  if (contaId !== CONFIG.CHATWOOT_NIO_ACCOUNT || caixaId !== CONFIG.CHATWOOT_NIO_INBOX) return [];
  // Prompt 18 (A): conversa RESOLVIDA no Chatwoot encerra o ciclo da Mari (handoff fechado, histórico mantido) — o nó
  // 2v chama mari_encerrar_ciclo. Reaberta sem dono, a Mari volta sabendo o histórico; com dono/time/nao-contatar,
  // o guard 2h continua calando. No evento de status o corpo É a conversa (id, status, inbox_id).
  // Eventos de conversa (o corpo É a conversa): status do Chatwoot sempre; "resolvida" ainda fecha o ciclo (2v).
  if (b.event === 'conversation_status_changed' || b.event === 'conversation_updated') {
    const cid = String(b.id ?? b.conversation?.id ?? '');
    const cwStatus = statusDe(b.conversation || b, cid);
    if (b.event === 'conversation_status_changed' && b.status === 'resolved' && cid) {
      return [{ json: { encerrar: false, registrar: 'resolvida', modo: 'chatwoot', canal: 'whatsapp', chatwootConversationId: cid, cwStatus } }];
    }
    return cwStatus ? [{ json: { soStatus: true, cwStatus } }] : [];
  }
  if (b.event && b.event !== 'message_created') return [];

  const p = b.payload || b;
  const msg = p.message || p;
  const conv = p.conversation || {};
  const sender = msg.sender || conv.meta?.sender || p.sender || {};
  const tipo = msg.message_type ?? p.message_type;
  const entrante = tipo === 0 || tipo === 'incoming' || (msg.sender_type || p.sender?.type) === 'contact';
  const convId = String(conv.id || msg.conversation_id || p.conversation_id || '');
  if (!convId) return [];
  const cwStatus = statusDe(conv, convId);
  if (msg.private) return cwStatus ? [{ json: { soStatus: true, cwStatus } }] : [];

  // Fala do consultor no Chatwoot (saída, não privada, de um usuário): vira turno 'humano' no histórico da Mari,
  // sem resposta. O eco do envio da própria Mari tem o mesmo formato (mesmo usuário do token) — quem o separa é
  // o mari_registrar_turno (texto igual a uma fala da Mari nos últimos 10 min = eco, ignorado).
  const soStatus = cwStatus ? [{ json: { soStatus: true, cwStatus } }] : [];
  const saida = tipo === 1 || tipo === 'outgoing';
  if (saida) {
    if (String(sender.type || msg.sender_type || '').toLowerCase() !== 'user') return soStatus;
    const textoH = String(msg.content || p.content || '').trim();
    const contato = conv.meta?.sender || {};
    const telH = String(contato.phone_number || conv.contact_inbox?.source_id || '').replace(/\D/g, '');
    if (!textoH || !/^\d{10,15}$/.test(telH)) return soStatus;
    return [{ json: { encerrar: false, registrar: 'humano', modo: 'chatwoot', canal: 'whatsapp', telefone: telH,
      nome: String(contato.name || '').trim(), texto: textoH, chatwootConversationId: convId, cwStatus } }];
  }
  if (!entrante) return soStatus;
  const atts = (msg.attachments || p.attachments || []).filter((a) => a && typeof a === 'object');
  const att = atts[0] || {};
  const ft = String(att.file_type || '').toLowerCase();
  // 12/11 (Prompt_midia_transcricao): TODOS os anexos. Áudio e imagem até 16 MB são baixados para o bucket privado
  // (cadeia 2b); vídeo, documento e o resto ficam só registrados (o time abre no Chatwoot). A transcrição que o próprio
  // Chatwoot às vezes manda (transcribed_text) é aproveitada sem custo.
  const LIM = 16 * 1024 * 1024;
  const anexos = atts.map((a, i) => {
    const f = String(a.file_type || '').toLowerCase();
    const tipo = f === 'image' ? 'imagem' : (f === 'audio' || f === 'voice') ? 'audio' : f === 'video' ? 'video' : f === 'location' ? 'local' : f === 'sticker' ? 'figurinha' : 'arquivo';
    const tam = Number(a.file_size) || null;
    const url = String(a.data_url || '');
    return { n: i, tipo, mime: String(a.content_type || '') || null, ext: String(a.extension || '').replace(/[^a-z0-9]/gi, '').toLowerCase() || null,
      tamanho: tam, url: /^https:\/\//.test(url) ? url : null, cw_transcricao: String(a.transcribed_text || '').trim() || null,
      baixar: ['audio', 'imagem'].includes(tipo) && /^https:\/\//.test(url) && (!tam || tam <= LIM) };
  }).filter((a) => a.tipo !== 'local');
  const msgId = String(msg.id ?? p.id ?? Date.now());
  const ca = msg.content_attributes || p.content_attributes || {};
  let texto = textoDoBotao(msg.content || p.content || '', ca.button_reply_id || ca.id || (ca.interactive && ca.interactive.id));
  if (ft === 'image') texto = ['[Imagem enviada pelo cliente]', texto].filter(Boolean).join('\n');
  else if (ft === 'location') texto = ['[Localização enviada pelo cliente]', texto].filter(Boolean).join('\n');
  else if (ft && !texto) texto = `[MIDIA:${MIDIA_SO.has(ft) ? ft : 'attachment'}]`;
  if (!texto) return soStatus;
  entrada = {
    canal: 'whatsapp', telefone: String(sender.phone_number || '').replace(/\D/g, ''),
    nome: String(sender.name || '').trim(), texto,
    origem: origemDoTexto(texto), chatwootConversationId: convId,
    contatoId: sender.id ?? conv.meta?.sender?.id ?? null,   // v7 (A9): nome do contato no handoff
    cwStatus,
    anexos: anexos.length ? anexos : null,
    baixarMidia: anexos.some((a) => a.baixar),
    msgId,
  };
  if (!/^\d{10,15}$/.test(entrada.telefone)) return soStatus;
  // 08/11 (0062): "#zerar" = comando de teste — encerra a conversa da Mari e a próxima mensagem começa do zero. Quem pode
  // é o banco que decide (config_mari_textos.telefones_teste); número fora da lista segue o fluxo normal como fala comum.
  if (/^\s*[#/]\s*zerar\s*$/i.test(texto)) entrada.registrar = 'zerar';
} else {
  return [];
}

// Rate limit (orçamento de chamadas ao Claude por hora, padrão Renata).
sd._apiCalls = (sd._apiCalls || []).filter((t) => Date.now() - t < 3600000);
if (sd._apiCalls.length >= CONFIG.MAX_CHAMADAS_HORA) {
  return fim({ erro: `orçamento esgotado (${sd._apiCalls.length}/${CONFIG.MAX_CHAMADAS_HORA} por hora)` });
}
sd._apiCalls.push(Date.now());

// modo DESTA execução: 'teste' (rota de teste) ou 'chatwoot' (webhook do Chatwoot, só com o interruptor em chatwoot).
const modoExec = entrada.canal === 'teste' ? 'teste' : 'chatwoot';
return [{ json: { encerrar: false, modo: modoExec, config: CONFIG, ...entrada } }];

// NIOGEN | n8n/mari/n02b_anexos.js — nó "2b · Anexos" do mari_principal (12/11/2026, 0145)
// docs/Prompt_midia_transcricao_121126_0230.md. Um item por anexo que vai para o bucket privado midia_conversas
// (áudio e imagem até 16 MB). Caminho: mari/<conversa do Chatwoot>/<mensagem>_<n>.<ext>. Sem segredo, sem texto de negócio.
// transcrever = áudio sem a transcrição do próprio Chatwoot (essa vem de graça e é usada no 2b8).
const e = $('2 · Entrada').first().json;
const PADRAO = { audio: 'ogg', imagem: 'jpg' };
const MIME = { ogg: 'audio/ogg', oga: 'audio/ogg', opus: 'audio/ogg', mp3: 'audio/mpeg', m4a: 'audio/mp4', mp4: 'audio/mp4', aac: 'audio/aac',
  amr: 'audio/amr', wav: 'audio/wav', jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png', webp: 'image/webp' };
const conv = String(e.chatwootConversationId || 'sem-conversa').replace(/[^0-9A-Za-z_-]/g, '');
const msg = String(e.msgId || Date.now()).replace(/[^0-9A-Za-z_-]/g, '');
const out = [];
for (const a of e.anexos || []) {
  if (!a.baixar) continue;
  const ext = a.ext && MIME[a.ext] ? a.ext : PADRAO[a.tipo];
  // tipo base sem parâmetros ("audio/ogg; codecs=opus" → "audio/ogg"): o bucket só aceita a lista da 0145.
  const base = String(a.mime || '').split(';')[0].trim().toLowerCase();
  const mime = Object.values(MIME).includes(base) ? base : MIME[ext];
  out.push({ json: { n: a.n, tipo: a.tipo, url: a.url, ext, mime, tamanho: a.tamanho,
    caminho: `mari/${conv}/${msg}_${a.n}.${ext}`, transcrever: a.tipo === 'audio' && !a.cw_transcricao } });
}
return out;

// NIOGEN | n8n/mari/n02b8_juntar.js — nó "2b8 · Juntar mídia" do mari_principal (12/11/2026, 0145)
// docs/Prompt_midia_transcricao_121126_0230.md. Junta o que a cadeia 2b fez (subida no bucket, link curto para o Claude,
// transcrição) numa entrada só, que segue o fluxo normal (2z → … → 3a / 2r gravam a lista em mari_turnos.midia).
//   · Áudio transcrito: a marca [MIDIA:audio] vira "🎤 (áudio) <transcrição>" e o turno passa pela IA (sai do soMidia).
//   · Sem transcrição (credencial desligada, erro, vazio): a marca fica → 2c responde a frase fixa e grava o erro.
//   · Foto: o texto segue "[Imagem enviada pelo cliente]"; o link url_ia (15 min) leva a foto ao Claude no 5b.
// Nada aqui derruba a entrada: qualquer falha vira "erro" no item da mídia e a mensagem segue.
const e = $('2 · Entrada').first().json;
const pega = (n) => { try { return $(n).isExecuted ? $(n).all() : []; } catch (x) { return []; } };
const itens = pega('2b · Anexos').map((i) => i.json);
const subidas = pega('2b2 · Subir mídia').map((i) => i.json || {});
const links = pega('2b3 · Link IA').map((i) => i.json || {});
const trans = pega('2b7 · Transcrever').map((i) => i.json || {});
const SB = 'https://zlrfwbkblytnokuexjti.supabase.co';
const agora = new Date();
const errDe = (j) => (j && j.error ? String(j.error.message || j.error.description || j.error).slice(0, 200) : null);

const porN = {};
itens.forEach((it, i) => {
  const up = subidas[i] || {};
  const lk = links[i] || {};
  const okUp = !errDe(up) && !!(up.Key || up.Id || up.key || up.id);
  const r = { caminho: okUp ? it.caminho : null, erro: okUp ? null : `não subiu: ${errDe(up) || 'sem resposta'}` };
  if (okUp && it.tipo === 'imagem' && lk.signedURL) {
    r.url_ia = `${SB}/storage/v1${lk.signedURL}`;
    r.url_ia_ate = new Date(agora.getTime() + 14 * 60000).toISOString();
  }
  porN[it.n] = r;
});
// Transcrições: na ordem dos áudios marcados para transcrever (o filtro 2b5 mantém a ordem).
const aTrans = itens.filter((it) => it.transcrever);
aTrans.forEach((it, i) => {
  const t = trans[i];
  const r = porN[it.n];
  // Nó 2b7 desligado (sem a credencial) passa o item adiante sem "text": conta como desligada, não como vazia.
  if (!t || (!errDe(t) && !Object.prototype.hasOwnProperty.call(t, 'text'))) { r.erro = r.erro || 'transcrição desligada (sem a credencial "Transcrição Nio")'; return; }
  const txt = String(t.text || '').trim();
  if (errDe(t)) r.erro = `transcrição falhou: ${errDe(t)}`;
  else if (!txt) r.erro = 'transcrição vazia';
  else { r.transcricao = txt.slice(0, 4000); r.transcrito_em = agora.toISOString(); r.transcrito_por = 'openai'; }
});

const midia = (e.anexos || []).map((a) => {
  const r = porN[a.n] || {};
  const m = { tipo: a.tipo, mime: a.mime, ext: a.ext, tamanho: a.tamanho, caminho: r.caminho || null };
  if (a.tipo === 'audio') {
    if (a.cw_transcricao) { m.transcricao = a.cw_transcricao.slice(0, 4000); m.transcrito_em = agora.toISOString(); m.transcrito_por = 'chatwoot'; }
    else if (r.transcricao) { m.transcricao = r.transcricao; m.transcrito_em = r.transcrito_em; m.transcrito_por = r.transcrito_por; }
  }
  if (r.url_ia) { m.url_ia = r.url_ia; m.url_ia_ate = r.url_ia_ate; }
  if (r.erro) m.erro = r.erro;
  else if (!a.baixar && ['audio', 'imagem'].includes(a.tipo)) m.erro = 'não baixado (maior que 16 MB ou sem link)';
  return Object.fromEntries(Object.entries(m).filter(([, v]) => v !== null && v !== undefined));
});

// Texto do turno: cada áudio transcrito no lugar da marca (ou numa linha a mais, se o cliente também escreveu).
let texto = String(e.texto || '');
for (const m of midia.filter((x) => x.tipo === 'audio' && x.transcricao)) {
  const linha = `🎤 (áudio) ${m.transcricao}`;
  if (/\[MIDIA:(audio|voice)\]/i.test(texto)) texto = texto.replace(/\[MIDIA:(audio|voice)\]/i, linha);
  else texto = [texto, linha].filter(Boolean).join('\n');
}

const { anexos, ...resto } = e;
return [{ json: { ...resto, texto, midia: midia.length ? midia : null } }];

// NIOGEN | n8n/mari/n02w_seguir.js — nó "2w · Seguir entrada" do mari_principal (08/11/2026, 0062)
// "#zerar" de um número FORA de config_mari_textos.telefones_teste: não é comando — a mensagem volta para o fluxo normal
// (2m · Modo chatwoot?) com os dados do 2 · Entrada, como se fosse uma fala comum do cliente.
// 12/11 (0145): com mídia, a entrada que vale é a do 2b8 · Juntar mídia (texto com a transcrição + lista de mídia).
const e = (() => { try { if ($('2b8 · Juntar mídia').isExecuted) return $('2b8 · Juntar mídia').first().json; } catch (x) { /* sem mídia */ } return $('2 · Entrada').first().json; })();
const { registrar, ...resto } = e;
return [{ json: resto }];

// NIOGEN | n8n/mari/n02h_guard_humano.js — nó "2h · Guard humano" do mari_principal (04/11/2026)
// Padrão Renata (no2 §0a): humano atribuído, time atribuído ou conversa resolvida = Mari calada.
// 05/11 (prompt 16, adendo 2): etiqueta `nao-contatar` também cala a Mari, mesmo sem dono.
// Modo 'teste': não há Chatwoot → sempre "sem humano".
// Modo 'chatwoot': lê a resposta do nó "2g · Chatwoot conversa" (GET da conversa). Fail-open.

// 12/11 (0145): com mídia, a entrada que vale é a do 2b8 · Juntar mídia (texto com a transcrição + lista de mídia).
const e = (() => { try { if ($('2b8 · Juntar mídia').isExecuted) return $('2b8 · Juntar mídia').first().json; } catch (x) { /* sem mídia */ } return $('2 · Entrada').first().json; })();
if (e.modo !== 'chatwoot') return [{ json: { ...e, humano: false, guard: 'sem humano (modo teste)' } }];

const c = $input.first().json || {};
const assignee = c.meta?.assignee || c.assignee || null;
const teamId = c.meta?.team?.id ?? c.team_id ?? null;
const status = c.status || null;

const labels = Array.isArray(c.labels) ? c.labels : [];

let motivo = null;
if (labels.includes('nao-contatar')) motivo = 'etiqueta nao-contatar';   // adendo 2: não falar, mesmo sem dono
else if (assignee && (assignee.id ?? assignee.account_id)) motivo = 'humano atribuído';
else if (teamId && !labels.includes('handoff-venda')) motivo = 'time atribuído';
else if (status === 'resolved') motivo = 'conversa resolvida';

// Janela pós-handoff (Ricardo, 07/11 23h30 — migration 0061): venda passada ao backoffice (etiqueta handoff-venda, time
// atribuído pela automação) e AINDA SEM DONO → segue para o 3a; quem decide é o mari_entrada (handoff dados_completos há
// menos de N min — config_mari_textos.pos_handoff_minutos — e nenhuma fala do nosso time desde então). Fora disso ele
// devolve silêncio e a mensagem fica registrada, como no 2r. Alguém do time assumiu (dono) → calada, como sempre.
if (!motivo && teamId) return [{ json: { ...e, humano: false, guard: 'time sem dono + handoff-venda — janela pós-handoff (banco decide)' } }];

if (motivo) return [{ json: { ...e, humano: true, encerrar: true, saida: { silencio: true, motivo } } }];
return [{ json: { ...e, humano: false, guard: 'sem humano' } }];

// NIOGEN | n8n/mari/n03e_espera_lock.js — nó "3e · Espera lock" do mari_principal (04/11/2026)
// A conversa está sendo respondida por outra execução (lock). Espera 1 s e tenta de novo,
// até ~45 s (TTL do lock), como o processing lock da Renata (no2 §2b).
const MAX = 45;
return [{ json: { esgotado: $runIndex >= MAX, tentativa: $runIndex + 1 } }];

// NIOGEN | n8n/mari/n04_preparar.js — nó "4 · Preparar" do mari_principal (04/11/2026)
// Entrada: resultado 'ok' do mari_consolidar (mensagens pendentes juntas + histórico + conversa).
// Faz: (1) detecta turno só de mídia (vai para a resposta fixa, sem IA); (2) extrai CEP, número e
// complemento da mensagem; (3) CEP novo → ViaCEP (público). O resto (área, cluster, planos, DFV)
// é o mari_contexto no banco. Sem texto de negócio.

const r = $input.first().json;
const conv = r.conversa || {};
const msg = String(r.mensagem || '');
const linhas = msg.split('\n').map((l) => l.trim()).filter(Boolean);
const soMidia = linhas.length > 0 && linhas.every((l) => /^\[MIDIA:\w+\]$/.test(l));

const out = {
  conversa_id: conv.id, consolidado: r, soMidia,
  p_cep: null, p_numero: null, p_complemento: null, p_viacep: null, cepInvalido: false, viacepFalhou: false,
};
if (soMidia) return [{ json: out }];

const etapaEndereco = ['abertura', 'endereco', 'elegibilidade'].includes(conv.etapa) || !conv.cep || /\bcep\b/i.test(msg);

// (2a) CEP: 8 dígitos isolados (36070-480, 36070480, 36.070-480).
let resto = msg;
if (etapaEndereco) {
  const m = msg.match(/(?<![\d.])(\d{2})\.?(\d{3})[-\s]?(\d{3})(?![\d])/);
  if (m) {
    // O lookbehind/lookahead já descarta pedaço de CPF ou telefone formatado.
    out.p_cep = m[1] + m[2] + m[3];
    resto = msg.slice(0, m.index) + ' ' + msg.slice(m.index + m[0].length);
  }
}

// (2a') CEP que ficou no histórico sem consulta: o cliente mandou o CEP enquanto um humano atendia (a fala entra
// em mari_turnos, mas o guard cala a Mari antes desta consulta). Sem isso a conversa ficava sem endereço do CEP e
// sem planos — a Mari improvisava bairro e não conseguia mostrar as opções (teste real de 05/11, pendência 34).
if (!out.p_cep && !conv.cep && etapaEndereco) {
  const hist = Array.isArray(r.historico) ? r.historico : [];
  for (let k = hist.length - 1; k >= 0; k--) {
    if (hist[k].papel !== 'lead') continue;
    const m = String(hist[k].texto || '').match(/(?<![\d.])(\d{2})\.?(\d{3})[-\s]?(\d{3})(?![\d])/);
    if (m) { out.p_cep = m[1] + m[2] + m[3]; out.cepDoHistorico = true; break; }
  }
}

// ── v7 (prompt 27, A2/A3): rua que o CLIENTE escreveu ──
const normR = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const PREF = /^(rua|r|avenida|av|travessa|tv|alameda|al|estrada|est|praca|rodovia|rod|beco|largo)\.?\s+/;
const PARADA = new Set(['de', 'da', 'do', 'dos', 'das', 'e']);
const palavras = (s) => normR(s).replace(PREF, '').replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter((w) => w && !PARADA.has(w));
const RUA_RE = /\b(rua|r\.|avenida|av\.?|travessa|tv\.?|alameda|estrada|pra[cç]a|rodovia|beco)\s+([A-Za-zÀ-ÿ'.\s]{3,60}?)(?=\s*(?:,|;|\d|\bn[º°o.]|\bn[uú]mero|\bbairro|\bcep|$|\n|\.(?:\s|$)))/i;
const ruaDe = (t) => { const m = String(t || '').match(RUA_RE); return m ? `${m[1].replace(/\.$/, '')} ${m[2]}`.replace(/\s+/g, ' ').trim() : null; };
const ROT = /\b(?:n[º°o.]\s*|n[uú]mero\s*:?\s*|num\.?\s*|casa\s+)(\d{1,5}[a-zA-Z]?)\b/i;
// Número da casa escrito junto da rua ("Rua dos Artistas, 123") ou com rótulo ("número 45"), da fala mais nova para a mais antiga.
function numeroJuntoDaRua(textos) {
  for (const t of textos) {
    const s = String(t || ''); const mr = s.match(RUA_RE);
    const h = (mr && s.slice(mr.index + mr[0].length).match(/^\s*,?\s*(?:n[º°o.]\s*|n[uú]mero\s*:?\s*)?(\d{1,5}[a-zA-Z]?)\b/i)) || s.match(ROT);
    if (h) return h[1];
  }
  return null;
}
const leadsRecentes = (Array.isArray(r.historico) ? r.historico : []).filter((h) => h.papel === 'lead').slice(-6).reverse().map((h) => h.texto);
function ruaDoCliente() {
  for (const t of [msg, ...leadsRecentes]) { const x = ruaDe(t); if (x) return x; }
  return null;
}
const lev1 = (a, b) => {   // distância ≤ 1 (erro de digitação)
  if (a === b) return true;
  if (Math.abs(a.length - b.length) > 1 || Math.min(a.length, b.length) < 5) return false;
  let i = 0, j = 0, d = 0;
  while (i < a.length && j < b.length) {
    if (a[i] === b[j]) { i++; j++; continue; }
    if (++d > 1) return false;
    if (a.length > b.length) i++; else if (b.length > a.length) j++; else { i++; j++; }
  }
  return d + (a.length - i) + (b.length - j) <= 1;
};
// Diverge = troca de palavra (Sebastião ANTÔNIO × Sebastião PEDRO) ou mais de 1 palavra faltando/sobrando.
function ruaDiverge(cli, cep) {
  const a = palavras(cli), b = palavras(cep);
  if (!a.length || !b.length) return false;
  const sobraA = a.filter((w) => !b.some((x) => lev1(w, x)));
  const sobraB = b.filter((w) => !a.some((x) => lev1(w, x)));
  return (sobraA.length > 0 && sobraB.length > 0) || sobraA.length + sobraB.length > 1;
}
const ruaCli = ruaDoCliente();
const VIA = (cidade, rua) => `https://viacep.com.br/ws/MG/${encodeURIComponent(cidade)}/${encodeURIComponent(rua)}/json/`;
const DIG = (s) => String(s || '').replace(/\D/g, '');
const dadosConv = conv.dados || {};

// ── CEP pelas opções de rua — DADO GUARDADO, não o texto da Mari (correção de raiz, 07/11) ──
// Teste real 06/11 22h57 (conversa #1): o CEP da opção mostrada só existia no TEXTO da Mari, e o código o procurava na
// última fala dela; quando a Mari confirmou o endereço sem repetir o CEP, ele se perdeu (sem cidade, sem cluster, sem
// planos). Agora: (1) busca com UMA opção só → o CEP é gravado na mesma hora (a Mari confirma rua, bairro e CEP com o
// cliente); (2) várias opções → ficam em mari_conversas.dados.opcoes_rua (7 · Extrair grava) e a escolha do cliente
// ("2", "a segunda", o nome do bairro) é resolvida contra elas.
const escolha = msg.trim().toLowerCase().match(/^(?:a|o|op[cç][aã]o|n[º°o.]?)?\s*([1-3])\s*[.)!]?$|^(?:a |o )?(primeir|segund|terceir)[ao]$/);
const nEsc = escolha ? (escolha[1] ? Number(escolha[1]) : { primeir: 1, segund: 2, terceir: 3 }[escolha[2]]) : null;
const nega = /^(nao|nenhuma|nenhum|errad|outra|outro)\b/.test(normR(msg).trim());
const opcSalvas = !conv.cep && Array.isArray(dadosConv.opcoes_rua) && dadosConv.opcoes_rua.length ? dadosConv.opcoes_rua : null;
if (!out.p_cep && etapaEndereco && opcSalvas) {
  let alvo = nEsc ? opcSalvas[nEsc - 1] || null : null;
  if (!alvo && !nega) {
    const nm = normR(msg);
    const porBairro = opcSalvas.filter((o) => o.bairro && nm.includes(normR(o.bairro)));
    if (porBairro.length === 1) alvo = porBairro[0];
    else if (opcSalvas.length === 1) alvo = opcSalvas[0];
  }
  if (alvo) { out.p_cep = DIG(alvo.cep); out.cepDaLista = true; out.cepOrigem = 'opcao_rua'; out.limparOpcoes = true; }
  else if (nega) { out.limparOpcoes = true; out.opcoesRecusadas = ruaCli ? normR(ruaCli) : true; }
}

// Legado: conversas cujas opções foram mostradas antes desta correção (sem dados.opcoes_rua) — lê o texto da Mari.
if (!out.p_cep && etapaEndereco && !opcSalvas && !conv.cep) {
  const maris = (Array.isArray(r.historico) ? r.historico : []).filter((h) => h.papel === 'mari');
  const ultMari = maris.slice(-1)[0];
  let ceps = ultMari ? [...String(ultMari.texto || '').matchAll(/^\s*([1-3])\)[^\n]*?(\d{5})-?(\d{3})/gm)] : [];
  if (!ceps.length && ultMari) {
    const soltos = [...new Set([...String(ultMari.texto || '').matchAll(/\bCEP\s*(\d{5})-?(\d{3})\b/gi)].map((x) => x[1] + x[2]))];
    if (soltos.length === 1) ceps = [[null, '1', soltos[0].slice(0, 5), soltos[0].slice(5)]];
  }
  const curar = !!conv.numero;   // conversa que passou do endereço sem CEP (como a #1 de 06/11) se cura sozinha
  if (!ceps.length) {
    for (const h of maris.slice(curar ? -14 : -5, -1).reverse()) {
      const t = String(h.texto || '');
      const lst = [...t.matchAll(/^\s*([1-3])\)[^\n]*?(\d{5})-?(\d{3})/gm)];
      const sol = [...new Set([...t.matchAll(/\bCEP\s*(\d{5})-?(\d{3})\b/gi)].map((x) => x[1] + x[2]))];
      if (lst.length === 1) { ceps = lst; break; }
      if (lst.length > 1) break;
      if (sol.length === 1) { ceps = [[null, '1', sol[0].slice(0, 5), sol[0].slice(5)]]; break; }
    }
  }
  const afirma = ceps.length === 1 && !nega;
  if ((nEsc || afirma) && ceps.length) {
    const alvo = ceps.find((x) => Number(x[1]) === (afirma && !nEsc ? 1 : nEsc));
    if (alvo) { out.p_cep = alvo[2] + alvo[3]; out.cepDaLista = true; out.cepOrigem = 'opcao_rua'; }
  }
}

// Busca pela rua (sem CEP) no ViaCEP, na cidade (anúncio da campanha 1 = Juiz de Fora) — até 3 opções.
// Também refaz a busca quando o CEP veio de uma busca anterior e o cliente agora escreve OUTRA rua ("não, é a Rua X").
const ruaAgora = ruaDe(msg);
const endConv = conv.endereco_cep || {};
const refazBusca = !out.p_cep && !!conv.cep && dadosConv.cep_origem === 'busca_rua' && !!ruaAgora && !!endConv.logradouro && ruaDiverge(ruaAgora, endConv.logradouro);
const ruaBusca = refazBusca ? ruaAgora : ruaCli;
const recusada = !refazBusca && ruaBusca && (out.opcoesRecusadas || dadosConv.opcoes_rua_recusadas === normR(ruaBusca));
if (!out.p_cep && (!conv.cep || refazBusca) && etapaEndereco && ruaBusca && !recusada) {
  const cidade = (refazBusca ? null : conv.cidade)
    || (/juiz de fora|\bjf\b/i.test([msg, ...(r.historico || []).map((h) => h.texto)].join(' ')) ? 'Juiz de Fora' : null)
    || (['meta_ads', 'instagram', 'facebook'].includes(conv.origem) ? 'Juiz de Fora' : null)
    || conv.cidade;
  if (!cidade) out.ruaSemCidade = ruaBusca;
  else {
    try {
      // O ViaCEP precisa do nome como está no cadastro ("Sebastião Pedro DA Silva"): tenta o nome inteiro sem o
      // "Rua/Av."; sem resultado, tenta sem as palavras de ligação.
      const inteiro = ruaBusca.replace(/^(rua|r\.?|avenida|av\.?|travessa|tv\.?|alameda|estrada|pra[cç]a|rodovia|beco)\s+/i, '').trim();
      const busca = palavras(ruaBusca).join(' ');
      let lst = inteiro.length >= 3 ? await this.helpers.httpRequest({ method: 'GET', url: VIA(cidade, inteiro), json: true, timeout: 6000 }) : [];
      if ((!Array.isArray(lst) || !lst.length) && busca.length >= 3 && busca !== normR(inteiro)) {
        lst = await this.helpers.httpRequest({ method: 'GET', url: VIA(cidade, busca), json: true, timeout: 6000 });
      }
      const vistos = new Set();
      let cands = (Array.isArray(lst) ? lst : []).filter((x) => x && x.cep && !vistos.has(x.cep) && vistos.add(x.cep));
      // Mesmo nome de rua: "Rua Halfeld" não é a "Rua Altivo Halfeld" (se houver a de nome igual, só ela fica).
      const chave = (s) => palavras(s).sort().join(' ');
      const iguais = cands.filter((x) => chave(x.logradouro) === chave(ruaBusca));
      if (iguais.length) cands = iguais;
      // Rua longa = um CEP por faixa de número (ViaCEP "complemento": "de 2105 a 2325 - lado ímpar", "até 9/0010",
      // "de 4107/4108 ao fim", ou um número só = CEP de grande usuário). Com o número da casa, o CEP certo sai da faixa.
      const faixa = (comp) => {
        const s = normR(comp).replace(/\s+/g, ' ').trim();
        if (!s) return { tudo: true };
        const lado = /impar/.test(s) ? 1 : /\bpar\b/.test(s) ? 0 : null;
        const nums = (s.match(/\d+/g) || []).map(Number);
        if (/^ate\b/.test(s) && nums.length) return { de: 0, ate: Math.max(...nums), lado };
        if (/ao fim/.test(s) && nums.length) return { de: Math.min(...nums), ate: Infinity, lado };
        if (/^de\b/.test(s) && nums.length >= 2) return { de: Math.min(...nums), ate: Math.max(...nums), lado };
        if (/^\d+$/.test(s)) return { unico: nums[0] };
        return { tudo: true };   // "(Res M Marinho)", "lado par" sem números… vale a rua inteira
      };
      // Número: junto da rua/rotulado, ou a resposta curta "2000" ao pedido do número (rua com vários CEPs).
      const soNumero = (msg.trim().match(/^(?:n[º°o.]?\s*|n[uú]mero\s*:?\s*)?(\d{1,5})[a-zA-Z]?\s*$/i) || [])[1];
      const numBusca = Number(String(numeroJuntoDaRua([msg, ...leadsRecentes]) || soNumero || conv.numero || '').replace(/\D/g, '')) || null;
      const serve = (x, n) => {
        const f = faixa(x.complemento);
        if (f.unico !== undefined) return f.unico === n;
        if (f.tudo) return true;
        return n >= f.de && n <= f.ate && (f.lado === null || n % 2 === f.lado);
      };
      const temFaixas = cands.some((x) => { const f = faixa(x.complemento); return !f.tudo; });
      if (temFaixas) {
        if (numBusca) {
          const doNumero = cands.filter((x) => serve(x, numBusca));
          cands = doNumero;   // número fora de todas as faixas → nenhuma opção (a Mari pede o CEP)
        } else {
          cands = cands.filter((x) => faixa(x.complemento).unico === undefined);   // sem número: CEP de grande usuário não serve
        }
      }
      const opcoes = cands.slice(0, 3).map((x) => ({ logradouro: x.logradouro, bairro: x.bairro, cep: x.cep }));
      if (cands.length === 1) {
        out.p_cep = DIG(opcoes[0].cep); out.cepDaBusca = { rua: ruaBusca, ...opcoes[0] }; out.cepOrigem = 'busca_rua'; out.limparOpcoes = true;
      } else if (cands.length > 3 && temFaixas && !numBusca) {
        out.ruaPedeNumero = ruaBusca;   // muitos CEPs pelo número: pedir o número (não chutar 3 opções)
      } else if (cands.length > 1) out.opcoesRua = opcoes;
      else out.ruaNaoAchada = ruaBusca;
    } catch (e) { out.ruaNaoAchada = ruaBusca; }
  }
} else if (recusada && !out.p_cep && !conv.cep) out.opcoesRecusadasRua = ruaBusca;

const cepAtual = out.p_cep || conv.cep;

// (2b) Complemento explícito (o "não tem" vem pela tag [ENDERECO] do modelo).
if (cepAtual && ['abertura', 'endereco', 'elegibilidade'].includes(conv.etapa)) {
  // 10/11 (rodada única): "Casa A/B/C" e "Loja" (sem número) são o complemento que o Novo Pedido da Nio pede num menu.
  // Letra maiúscula ("Casa B") em qualquer mensagem; minúscula só na resposta curta ("casa b") — "casa e trabalho" não é.
  let c = resto.match(/\b(ap(?:to|artamento)?\.?\s*\d+\s*[a-z]?|bloco\s*\w+(?:\s*ap(?:to)?\.?\s*\d+)?|casa\s+(?:dos\s+)?fundos|fundos|lote\s*\d+\w*|sala\s*\d+\w*|loja\s*\d+\w*)\b/i);
  if (!c) {
    const casa = resto.match(/\b([Cc]asa\s+[A-E])(?![A-Za-z0-9])/) || (resto.trim().length <= 24 ? resto.match(/\b(casa\s+[a-e])(?![a-z0-9])/i) : null);
    if (casa) c = [casa[0], casa[1].replace(/\s+/g, ' ').replace(/^casa/i, 'Casa').replace(/[a-e]$/, (x) => x.toUpperCase())];
  }
  if (c) {
    out.p_complemento = c[1].replace(/\s+/g, ' ').trim();
    resto = resto.replace(c[1], ' ');   // número da casa não pode sair do complemento
  }
}

// (2c) Número da casa: com rótulo ("nº 123", "número 45", "casa 12") ou número solto numa mensagem curta.
if (cepAtual && (out.p_cep || !conv.numero)) {
  let num = null;
  const rot = resto.match(ROT);
  if (rot) num = rot[1];
  else if (/\bs\/?n\b|sem n[uú]mero/i.test(resto)) num = 's/n';
  else if (out.cepDoHistorico) {
    // CEP do histórico: número só com rótulo ("número 500"), procurado também nas falas antigas do cliente —
    // número solto na mensagem de agora ("quero o 1") não é número da casa.
    const hist = Array.isArray(r.historico) ? r.historico : [];
    for (let k = hist.length - 1; k >= 0 && !num; k--) {
      if (hist[k].papel !== 'lead') continue;
      const h = String(hist[k].texto || '').match(ROT);
      if (h) num = h[1];
    }
  } else if (!(out.cepDaLista && nEsc)) {
    // "2" que escolhe a opção de rua não é o número da casa.
    const curta = resto.replace(/\s+/g, ' ').trim();
    const solto = curta.match(/(?:^|[\s,;])(\d{1,5}[a-zA-Z]?)(?=$|[\s,;.])/);
    if (solto && curta.length <= 60 && !/\d{6,}/.test(curta.replace(/[.\-\s]/g, ''))) num = solto[1];
  }
  // CEP da opção/busca de rua: o número que o cliente escreveu junto da rua ("Rua dos Artistas, 123") numa fala anterior.
  if (!num && (out.cepDaLista || out.cepDaBusca)) num = numeroJuntoDaRua(leadsRecentes);
  if (num) out.p_numero = num.toUpperCase();
}
// CEP novo de uma opção/busca de rua = o MESMO endereço da conversa: o mari_contexto zera número e complemento quando o
// CEP muda, então o que o cliente já deu vai junto (teste real 07/11 00h26: a cura apagou o 123 e o "Apto 403").
if ((out.cepDaLista || out.cepDaBusca) && out.p_cep !== conv.cep) {
  if (!out.p_numero && conv.numero) out.p_numero = String(conv.numero);
  if (!out.p_complemento && conv.complemento) out.p_complemento = String(conv.complemento);
}

// (3) ViaCEP para CEP novo.
if (out.p_cep && out.p_cep !== conv.cep) {
  try {
    const v = await this.helpers.httpRequest({ method: 'GET', url: `https://viacep.com.br/ws/${out.p_cep}/json/`, json: true, timeout: 6000 });
    if (v && !v.erro && v.localidade) {
      out.p_viacep = { cep: v.cep, logradouro: v.logradouro || '', bairro: v.bairro || '', localidade: v.localidade, uf: v.uf };
    } else {
      out.cepInvalido = true;
    }
  } catch (e) {
